import assert from 'node:assert/strict';
import {mkdtemp,rm,writeFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import path from 'node:path';
const dir=await mkdtemp(path.join(tmpdir(),'crew-people-proof-'));
process.env.CREW_DATA_DIR=dir;
const {startServer,createContext,child}=await import('./acceptance-runtime.mjs');
const people=await import('./checks/people.mjs');
let server;const ids={},checks=[];
try{
  server=await startServer();
  let ctx=createContext(server.url,ids,checks);
  await ctx.signup('owner',{name:'Proof Owner',email:'proof-owner@crew.test',password:'proof owner long password'});
  await people.smoke(ctx);
  if(process.argv.includes('--browser')) {
    for(let i=0;i<26;i++)await ctx.api('POST','/orgs/'+ids.orgId+'/teams',{name:'Browser list '+i});
    const team=(await ctx.api('POST','/orgs/'+ids.orgId+'/teams',{name:'Browser administration',description:'Before browser'})).team;
    ids.browserTeamId=team.id;
    const state=path.join(dir,'browser-state.json');await writeFile(state,JSON.stringify(ids),{mode:0o600});
    const run=await child('/usr/bin/python3',['scripts/people-browser.py'],{env:{...process.env,CREW_PEOPLE_URL:server.url,CREW_PEOPLE_STATE:state},deadline:75000});
    const result=JSON.parse(run.stdout.trim().split('\n').at(-1));assert.equal(result.ok,true);checks.push(...result.checks);
    assert.equal((await ctx.api('GET','/teams/'+team.id)).team.description,'Browser persisted description');
  }
  await server.stop();server=null;
  server=await startServer();ctx=createContext(server.url,ids,checks);
  await people.restart(ctx);await people.audit({checks});
  console.log(JSON.stringify({ok:true,newServerProcess:true,checks}));
}finally{if(server)await server.stop();await rm(dir,{recursive:true,force:true});}
